{
  "name": "FieldFox 手持式矢量网络分析仪",
  "name_en": "FieldFox Handheld Vector Network Analyzer",
  "manufacturer": "Keysight Technologies",
  "description": "FieldFox 是一类便携式射频/微波矢量网络分析仪，用于对器件和网络进行扫频测量并获取 S 参数响应。它常用于实验室和现场测试中的滤波器、放大器、传输线及其他射频微波部件表征。",
  "description_en": "FieldFox is a portable RF/microwave vector network analyzer used to sweep frequency and measure S-parameter responses of devices and networks. It is commonly used in laboratories and field testing to characterize filters, amplifiers, transmission lines, and other RF/microwave components.",
  "tag_hints": [
    "vector network analysis",
    "handheld RF analyzer",
    "S-parameter measurement",
    "microwave frequency sweep",
    "IF bandwidth control",
    "field testing"
  ],
  "actions": [
    {
      "action_name": "auto-points",
      "description": "获取/设置扫频点数",
      "description_en": "Get/set the number of sweep points"
    },
    {
      "action_name": "auto-start",
      "description": "获取/设置起始频率",
      "description_en": "Get/set the start frequency"
    },
    {
      "action_name": "auto-stop",
      "description": "获取/设置终止频率",
      "description_en": "Get/set the stop frequency"
    },
    {
      "action_name": "auto-bandwidth",
      "description": "获取/设置中频带宽",
      "description_en": "Get/set the IF bandwidth"
    },
    {
      "action_name": "auto-display",
      "description": "获取/设置显示模式",
      "description_en": "Get/set the display mode"
    },
    {
      "action_name": "auto-trigger",
      "description": "获取/设置触发模式",
      "description_en": "Get/set the trigger mode"
    },
    {
      "action_name": "auto-format",
      "description": "获取/设置迹线显示格式",
      "description_en": "Get/set the trace display format"
    },
    {
      "action_name": "auto-sparameter",
      "description": "获取/设置测量的 S 参数",
      "description_en": "Get/set the measured S-parameter"
    },
    {
      "action_name": "auto-sweep",
      "description": "执行一次扫频测量",
      "description_en": "Perform a sweep measurement"
    },
    {
      "action_name": "auto-readRI",
      "description": "读取实部/虚部形式的测量数据",
      "description_en": "Read measurement data in real/imaginary form"
    },
    {
      "action_name": "auto-readFormatted",
      "description": "读取格式化后的测量数据",
      "description_en": "Read formatted measurement data"
    }
  ]
}

